"""Reconstruct the exact frozen a3 protocol without launching any experiment."""
import base64, gzip, hashlib
from pathlib import Path
DATA = ''
EXPECTED = "4558c7dc83c5eda06cebecb1dfb59978aec0e8a827b5985e711a863522aaa049"
b = gzip.decompress(base64.b64decode(DATA))
assert hashlib.sha256(b).hexdigest() == EXPECTED
p = Path(__file__).resolve().parent / "protocol.json"
if p.exists():
    assert p.read_bytes() == b, "Refusing to overwrite a different protocol"
else:
    p.write_bytes(b)
print(EXPECTED)
